// ----------------------------------------------------------------------------
// 2Z. PROJECT SITES
//     Inland destinations you can pick as a corridor endpoint. A site borrows
//     its host nation's profile (blocs, trade, macro figures) but routes to
//     its own node, e.g. China -> Tema -> road -> Tamale.
// ----------------------------------------------------------------------------
export const SITES = {
  TAMALE: { id: 'TAMALE', name: 'Tamale, Northern Ghana (project site)', host: 'GHA', node: 'N_GH_TAMALE' }
};

// ----------------------------------------------------------------------------
// 3. NORMALIZE PORTS
//    A port entry is either a node ID or { id, penaltyNM, note } for a
//    SECONDARY port that handles only part of national volumes. The penalty
//    is a routing cost (not distance), so the router prefers the main port
//    and only switches when the main one is cut off — e.g. UAE -> Fujairah
//    when Hormuz closes.
//      n.ports : [{ id, penaltyNM, note }]   n.nodes : [ids]   n.node : primary
// ----------------------------------------------------------------------------
for (const n of Object.values(NATIONS)) {
  n.ports = n.nodes.map(p => (typeof p === 'string' ? { id: p, penaltyNM: 0 } : { penaltyNM: 0, ...p }));
  n.nodes = n.ports.map(p => p.id);
  n.node = n.nodes[0];
}
